let li=0;
function showLb(){const g=G[li];$('#lbi').src=g.s;$('#lbt').textContent=g.t+'  ·  '+(li+1)+'/'+G.length;$('#lb').classList.add('on')}
function lb(a){if(a==='x'){$('#lb').classList.remove('on');return}li=(li+(a==='n'?1:-1)+G.length)%G.length;showLb()}
let tx=0;const LB=document.getElementById('lb');LB.addEventListener('touchstart',e=>{tx=e.touches[0].clientX},{passive:true});LB.addEventListener('touchend',e=>{const d=e.changedTouches[0].clientX-tx;if(Math.abs(d)>50)lb(d<0?'n':'p')});
